window.VPQ_HOSPITAL_JOURNEYS=Object.freeze({caseFiles:[{"id":"hospital-cat-urethral-obstruction-26","name":"Cosmo · blocked male cat","emoji":"🐈","species":"Cat","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"A neutered male cat is vocalizing, repeatedly visiting the litter box, producing little urine, and vomiting. This is a simulated emergency; serial findings become available as the case advances.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"The owner says Cosmo is straining. Which front-desk decision is safest?","options":["Treat it as a potentially life-threatening urinary obstruction and request immediate clinical triage","Assume constipation and schedule next week","Recommend a diuretic at home"],"answer":0,"why":"A male cat unable to pass urine may rapidly develop hyperkalemia, acid-base disturbances and cardiovascular instability. Straining must not automatically be assumed to be constipation.","tag":"Urgency and triage","findings":"The owner confirms almost no urine passed overnight and reduced activity."},{"room":"reception","q":"Which focused question most changes the urgency of the history?","options":["Whether the cat prefers wet or dry food","Last confirmed urination, vomiting, previous obstruction and degree of lethargy","The coat color and litter brand alone"],"answer":1,"why":"The timing of oliguria or anuria plus systemic signs helps estimate obstruction duration and risk. History helps triage but does not replace examination.","tag":"History","findings":"Cosmo arrives weak and dehydrated; bladder is large and painful on gentle examination."},{"room":"exam","q":"What is the most useful immediate evaluation alongside a focused exam?","options":["ECG, electrolytes and renal/acid-base assessment with stabilization planning","Only a fecal flotation","A routine allergy panel"],"answer":0,"why":"Obstructed cats can develop dangerous potassium and acid–base abnormalities and azotemia. Obtain ECG and essential laboratory data without delaying lifesaving stabilization.","tag":"Diagnostics","findings":"ECG shows peaked T waves; potassium is 7.2 mmol/L (example feline reference 3.5–5.5 mmol/L)."},{"room":"exam","q":"What is the appropriate response to the elevated potassium and concerning ECG?","options":["Delay treatment until urine culture results","Urgent cardiac membrane stabilization when indicated, controlled correction of hyperkalemia and obstruction relief","Give potassium supplementation as the first intervention"],"answer":1,"why":"Hyperkalemia impairs cardiac conduction. IV calcium gluconate may protect myocardium temporarily when clinically indicated, while other treatments shift or remove potassium and relieving obstruction addresses the source. Protocols require monitoring.","tag":"Decision and physiology","findings":"After emergency stabilization, urethral catheterization restores urine outflow."},{"room":"treatment","q":"What inpatient monitoring is particularly important after unblocking?","options":["Urine output, fluid balance, renal values and serial electrolytes","Only daily body weight without urine measurement","Stop monitoring because the obstruction is resolved"],"answer":0,"why":"Postobstructive diuresis, changing potassium, perfusion and renal function can require ongoing treatment adjustments. Record urine output and reassess hydration frequently.","tag":"Treatment monitoring","findings":"Urine production increases after decompression; potassium trends downward with monitored treatment."},{"room":"treatment","q":"Which discharge plan best supports safe recovery?","options":["No follow-up because the catheter passed successfully","Analgesia, individualized urinary management, recurrence precautions and clear instructions for urgent reassessment if straining or anuria returns","Empiric antibiotics for every case regardless of evidence"],"answer":1,"why":"Preventing recurrence requires cause assessment, dietary/environmental changes when appropriate and client education. Antibiotics are not automatically indicated without evidence of infection.","tag":"Discharge and prevention","findings":"Cosmo is comfortable, urinating spontaneously and ready for individualized follow-up."}]},{"id":"hospital-dog-hemolytic-anemia-26","name":"Luna · pale and jaundiced dog","emoji":"🐕","species":"Dog","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"Adult dog with acute weakness, pale gums and yellow sclera. This teaching case follows triage, anemia interpretation, diagnostics and inpatient monitoring.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"Which check-in finding requires immediate escalation?","options":["Collapse, tachycardia and very pale mucous membranes","A preference for a particular treat","Mild shedding without systemic signs"],"answer":0,"why":"Pallor and weakness can indicate inadequate oxygen delivery from severe anemia, hemorrhage or circulatory shock. Stabilization takes priority over completing a routine intake.","tag":"Triage","findings":"Luna is weak, tachycardic and icteric, without an obvious external bleed."},{"room":"reception","q":"What history helps narrow causes of anemia and jaundice?","options":["Recent medications or toxins, travel/vector exposure, bleeding, previous illness and transfusion history","Favorite sleeping spot only","Whether the owner prefers tablets or capsules"],"answer":0,"why":"Drug or toxin exposure, infections, blood loss and prior transfusions can change the differential diagnosis and guide safe testing.","tag":"Focused history","findings":"Point-of-care PCV is 18% (example canine reference 37–55%); total protein is 6.8 g/dL (example 5.5–7.5)."},{"room":"exam","q":"What is the best interpretation of severe anemia with relatively preserved total protein?","options":["Blood loss is impossible","Hemolysis becomes an important differential, but CBC, smear and additional findings are needed","The PCV proves marrow neoplasia"],"answer":1,"why":"Preserved protein may make acute external blood loss less obvious; it does not establish hemolysis. Evaluate smear, reticulocytes, bilirubin and other possible causes.","tag":"Clinical pathology","findings":"Smear shows spherocytes and persistent saline agglutination; reticulocytes are increased."},{"room":"exam","q":"Which conclusion is most defensible?","options":["Findings strongly support an immune-mediated hemolytic process while triggers and alternatives still require investigation","Spherocytes prove one specific infectious organism","Rouleaux and agglutination are identical"],"answer":0,"why":"Spherocytes and true agglutination with anemia support immune-mediated hemolysis. Infectious, neoplastic or other triggers and transfusion risks still require evaluation.","tag":"Differentials","findings":"Luna remains tachycardic, with poor exercise tolerance despite initial stabilization."},{"room":"treatment","q":"Which monitored care strategy is most appropriate?","options":["Assess perfusion and need for transfusion, pursue cause-directed therapy and monitor for thrombosis and deterioration","Give oral iron as the sole emergency intervention","Wait for spontaneous marrow recovery without reassessment"],"answer":0,"why":"Severe hemolysis can reduce oxygen delivery despite regeneration. Decisions about transfusion and immunosuppression depend on the complete patient and differential diagnosis. Thromboembolic complications merit attention.","tag":"Inpatient care","findings":"Luna receives individualized care; PCV and vital signs are followed serially."},{"room":"treatment","q":"Which combination best tracks response?","options":["PCV/HCT, reticulocyte trend, bilirubin, clinical oxygen delivery and adverse effects","A single urine color check only","One normal temperature measurement"],"answer":0,"why":"Serial laboratory and clinical reassessment distinguishes stabilization, continued RBC destruction, marrow response and complications. A single number is not enough.","tag":"Monitoring and follow-up","findings":"Luna improves clinically with a monitored plan and a specific recheck schedule."}]},{"id":"hospital-rabbit-gi-26","name":"Clover · rabbit not eating","emoji":"🐇","species":"Rabbit","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"Adult pet rabbit with reduced fecal pellets, reduced appetite and hunched posture. Simulated exotics workflow; distinguish painful gastrointestinal hypomotility from obstruction.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"What is the best initial triage response?","options":["Urgent examination because anorexia and reduced fecal output in rabbits can deteriorate rapidly","Tell the owner to wait several days","Recommend unrestricted prokinetics before checking for obstruction"],"answer":0,"why":"Rabbits rely on continuous intake and gastrointestinal motility. Anorexia and reduced fecal output warrant prompt assessment for pain, dehydration, dental disease, obstruction and systemic illness.","tag":"Exotics triage","findings":"The owner reports no normal fecal pellets since the previous evening and reduced drinking."},{"room":"reception","q":"Which history is most informative?","options":["Diet and hay intake, fecal output, recent stress, dental history and access to foreign material","Whether the rabbit likes being photographed","The color of the cage door"],"answer":0,"why":"Dietary and fecal history helps identify precipitating problems. Dental pain, stress, dehydration and mechanical obstruction can all present similarly.","tag":"History","findings":"Clover is hunched and mildly hypothermic on presentation; abdomen is painful."},{"room":"exam","q":"Which next diagnostic approach best distinguishes ileus from a dangerous mechanical process?","options":["Focused examination and imaging when indicated, with hydration and glucose/electrolyte assessment","Diagnose uncomplicated stasis from reduced feces alone","Offer a new toy and skip assessment"],"answer":0,"why":"Gastrointestinal hypomotility is a syndrome, not a definitive cause. Gastric distension, obstructive patterns and metabolic instability alter feeding, medication and intervention decisions.","tag":"Diagnostic reasoning","findings":"Radiographs raise concern for substantial gastric distension and a possible obstructive pattern."},{"room":"exam","q":"What is safest given possible obstruction?","options":["Avoid force-feeding or routine prokinetics until obstruction is assessed and stabilize while obtaining exotics/surgical consultation","Give aggressive oral feeding immediately regardless of findings","Assume all rabbit anorexia is normal hairball passage"],"answer":0,"why":"Forced feeding and prokinetics may be unsafe with mechanical obstruction. Analgesia, resuscitation and urgent investigation are priorities, with definitive treatment based on the cause.","tag":"Safety decision","findings":"Further assessment excludes a mechanical obstruction; the clinician diagnoses painful functional hypomotility."},{"room":"treatment","q":"What comprehensive treatment approach now makes sense?","options":["Analgesia, corrected hydration, nutritional support as appropriate and treatment of the underlying cause, with close reassessment","An antibiotic in every case without indication","Withhold pain relief because it can mask the diagnosis"],"answer":0,"why":"Once obstruction is reasonably excluded, support for motility, hydration and intake may be appropriate. Pain control and addressing dental or systemic causes are central.","tag":"Exotics treatment","findings":"Clover begins eating hay and producing small fecal pellets."},{"room":"treatment","q":"Which recovery indicators matter most?","options":["Increasing voluntary hay consumption, fecal quantity/quality, comfort, temperature and hydration","A single pellet regardless of behavior","Weight gain from fluids alone"],"answer":0,"why":"Recovery requires sustained intake and gastrointestinal output plus comfort and clinical stability. Relapse or recurrent anorexia demands reassessment.","tag":"Recovery monitoring","findings":"Clover is brighter with sustained intake; a home-monitoring and recheck plan is discussed."}]},{"id":"hospital-dog-pyometra-26","name":"Daisy · fever and vaginal discharge","emoji":"🐕","species":"Dog","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"Older intact female dog with lethargy, increased drinking, vomiting and vaginal discharge several weeks after estrus. The simulated patient requires a coordinated emergency workflow.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"Which concern should the receptionist flag urgently?","options":["Possible pyometra and systemic infection in an intact female dog","Routine seasonal shedding","Uncomplicated dietary indiscretion with no examination needed"],"answer":0,"why":"Pyometra can cause severe systemic inflammation, dehydration, endotoxemia and sepsis. Open-cervix discharge does not mean the patient is safe.","tag":"Red-flag triage","findings":"Daisy's owner confirms recent heat and worsening lethargy."},{"room":"reception","q":"Which additional history helps prioritize the assessment?","options":["Estrus timing, reproductive history, discharge, vomiting, drinking and progression of illness","Last grooming appointment alone","Favorite walking route only"],"answer":0,"why":"Post-estrus timing and clinical signs support the reproductive differential. History must be paired with a perfusion assessment and diagnostics.","tag":"Intake","findings":"Daisy has fever, tachycardia and painful abdominal palpation."},{"room":"exam","q":"What diagnostic combination best evaluates suspected pyometra and organ effects?","options":["Abdominal ultrasound together with CBC, chemistry, hydration/perfusion assessment and appropriate other testing","External discharge appearance alone","A skin scraping as the primary test"],"answer":0,"why":"Ultrasound can detect a distended fluid-filled uterus; bloodwork assesses inflammation and organ involvement. Pregnancy and other fluid-filled uterine conditions are differentials.","tag":"Diagnostic work-up","findings":"Ultrasound reveals a fluid-distended uterus; CBC suggests marked inflammatory response."},{"room":"exam","q":"Which plan most appropriately addresses the likely disease?","options":["Stabilization and urgent surgical evaluation for ovariohysterectomy when appropriate","Discharge with observation alone because the cervix is open","Routine elective spay months later without reassessment"],"answer":0,"why":"Ovariohysterectomy is definitive for most clinically ill dogs with pyometra. Correct perfusion problems and provide appropriate perioperative support; individual cases require clinical judgment.","tag":"Clinical decision","findings":"Daisy undergoes surgery after stabilization; intraoperative findings confirm purulent uterine contents."},{"room":"treatment","q":"What is most important during the immediate postoperative period?","options":["Monitor perfusion, pain, urine output, temperature and organ function; provide indicated antimicrobial and supportive care","Monitor only the incision color","Stop fluids and other monitoring regardless of recovery"],"answer":0,"why":"Sepsis-associated or perioperative complications can evolve after source control. Tailor analgesia, fluids, monitoring and antimicrobial treatment to severity and clinical findings.","tag":"Postoperative care","findings":"Daisy's perfusion and appetite improve, and follow-up chemistry is planned."},{"room":"treatment","q":"Which owner instructions best complete the patient journey?","options":["Wound care, prescribed medications, activity restriction, recheck timing and urgent signs of deterioration","No recheck is needed after surgery","Allow unrestricted activity immediately"],"answer":0,"why":"Clear discharge instructions and monitoring for poor appetite, worsening lethargy, fever, vomiting or wound complications support safe recovery.","tag":"Discharge follow-up","findings":"Daisy goes home with written instructions and a recheck appointment."}]},{"id":"hospital-addisonian-dog-26","name":"Maple · collapsing dog with Addisonian crisis","emoji":"🐕","species":"Dog","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"An adult mixed-breed dog presents after repeated vomiting, diarrhea and weakness. The owner says Maple has been unwell intermittently for weeks. This case combines endocrine disease, shock, electrolyte interpretation and long-term management.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"Maple arrives weak, bradycardic for the degree of shock and poorly perfused. What should happen first?","options":["Immediate emergency triage and stabilization while the clinician evaluates shock","Schedule a routine wellness visit next month","Recommend a dietary change and send home"],"answer":0,"why":"Hypovolemic shock and an unexpectedly slow heart rate can occur with severe hyperkalemia. Stabilization and rapid assessment cannot wait for a definitive endocrine diagnosis.","tag":"Emergency triage","findings":"Maple has weak pulses, delayed capillary refill and dehydration."},{"room":"reception","q":"Which history would most strengthen suspicion of hypoadrenocorticism?","options":["Episodic vomiting/diarrhea, weight loss, weakness and recent medication exposure","Favorite brand of chew toy","Coat color alone"],"answer":0,"why":"Hypoadrenocorticism often causes waxing-and-waning gastrointestinal illness and weakness. Ask about previous glucocorticoid use as well as other causes of similar clinical signs.","tag":"History","findings":"The owner recalls recurrent unexplained GI episodes and declining appetite."},{"room":"exam","q":"Chemistry shows Na 124 mmol/L and K 7.1 mmol/L. Example canine intervals: Na 140–155, K 3.5–5.5 mmol/L. What is the most important interpretation?","options":["Severe hyponatremia and hyperkalemia can support mineralocorticoid deficiency but are not diagnostic alone","Normal electrolytes for this dog","Primary hyperthyroidism is confirmed"],"answer":0,"why":"Deficient aldosterone decreases renal sodium retention and potassium excretion. Renal disease, urinary obstruction, severe GI illness and other causes must be considered. Calculate and interpret the Na:K ratio with context.","tag":"Electrolytes","findings":"ECG shows changes concerning for hyperkalemia; a pre-treatment cortisol sample is collected if feasible without delaying care."},{"room":"exam","q":"Which test is used to confirm spontaneous hypoadrenocorticism?","options":["ACTH stimulation test interpreted with treatment history and clinical findings","A single low sodium result","A urine dipstick alone"],"answer":0,"why":"The ACTH stimulation test evaluates adrenal cortisol response. A baseline cortisol can help exclude disease when sufficiently high, but a low baseline value alone does not confirm Addison's. Emergency treatment must not be delayed for testing.","tag":"Confirmatory testing","findings":"The clinician begins monitored emergency treatment; ACTH-stimulation results support hypoadrenocorticism."},{"room":"treatment","q":"Which acute plan best addresses the immediate threats?","options":["Carefully titrated IV fluids, serial ECG/electrolytes, indicated hyperkalemia management and appropriate glucocorticoid therapy","Potassium supplementation immediately, regardless of K","No monitoring once vomiting stops"],"answer":0,"why":"Hypovolemia and electrolyte disturbances can threaten circulation and conduction. Treatment choice and speed depend on hemodynamics, sodium correction rate, ECG and serial values.","tag":"Inpatient treatment","findings":"Perfusion improves, K falls and sodium begins to rise under monitoring."},{"room":"treatment","q":"Once Maple is stable, what long-term plan is most appropriate?","options":["Individualized glucocorticoid and, if needed, mineralocorticoid replacement with electrolyte and clinical monitoring","Stop all hormone therapy after the first improved appetite","Treat every relapse with empiric antibiotics only"],"answer":0,"why":"Primary hypoadrenocorticism usually needs lifelong replacement and dose adjustments. Maintenance medication, stress-dose counseling and scheduled electrolyte checks are part of safe management.","tag":"Discharge and chronic care","findings":"Maple returns for scheduled electrolyte reassessment and owner education."}]},{"id":"hospital-cat-pleural-effusion-26","name":"Nimbus · cat struggling to breathe","emoji":"🐈","species":"Cat","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"An older cat presents with acute labored breathing, crouched posture and reduced appetite. The case emphasizes low-stress triage, imaging decisions, pleural fluid interpretation and stabilization without assuming one cause.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"Nimbus arrives open-mouth breathing. What is the safest initial approach?","options":["Minimize handling and immediately provide oxygen and emergency assessment","Obtain a prolonged full history before oxygen support","Force the cat into dorsal recumbency for an extended exam"],"answer":0,"why":"Severely dyspneic cats can decompensate from stress. Oxygen, a calm environment and essential focused assessment take priority over stressful procedures.","tag":"Respiratory triage","findings":"Nimbus is breathing rapidly with a shallow restrictive pattern and muted ventral thoracic sounds."},{"room":"reception","q":"Which history helps prioritize cardiogenic and noncardiogenic causes?","options":["Onset, previous cardiac disease, trauma, toxin exposure, cough or fever and weight change","Favorite sleeping blanket only","Whether Nimbus prefers a window perch"],"answer":0,"why":"Respiratory disease may reflect pleural, pulmonary, cardiac or systemic processes. History helps guide differentials but severe distress limits how long intake can continue.","tag":"Focused intake","findings":"The clinician suspects pleural space disease and prepares a low-stress point-of-care ultrasound."},{"room":"exam","q":"Point-of-care ultrasound identifies moderate pleural effusion. What is the priority if breathing remains compromised?","options":["Therapeutic thoracocentesis when clinically indicated, with oxygen and monitoring","Wait for complete three-view radiographs before any decompression","Start a bronchodilator because all dyspnea is asthma"],"answer":0,"why":"Pleural fluid prevents normal lung expansion. Timely drainage can relieve restriction and provide a diagnostic sample; stabilize before extensive imaging if the patient cannot tolerate it.","tag":"Clinical decision","findings":"Thoracocentesis produces pale opaque fluid and improves respiratory effort."},{"room":"exam","q":"Fluid cytology shows numerous small lymphocytes; triglyceride concentration in the effusion exceeds serum. What does this pattern suggest?","options":["Chylous effusion, requiring evaluation for underlying disease","A definitive bacterial infection from fluid appearance alone","No pleural disease because oxygenation improved"],"answer":0,"why":"Chylous fluid is triglyceride-rich and commonly contains small lymphocytes. Causes can include cardiac disease, lymphatic abnormalities, neoplasia or idiopathic disease; fluid classification alone does not establish the source.","tag":"Clinical pathology","findings":"Diagnostic evaluation includes echocardiography as indicated and repeat thoracic assessment."},{"room":"treatment","q":"What should be monitored after drainage?","options":["Respiratory rate/effort, oxygenation, recurrence of fluid and the underlying disease","Coat grooming exclusively","Appetite only while ignoring respiratory effort"],"answer":0,"why":"Clinical relief can be transient if effusion reaccumulates. Serial respiratory assessment and investigation of etiology guide the next intervention.","tag":"Treatment monitoring","findings":"Nimbus breathes comfortably after stabilization but retains a risk of recurrence."},{"room":"treatment","q":"Which discharge plan best supports safety?","options":["Cause-specific therapy and a recheck plan, including owner instructions to return immediately for increased effort or open-mouth breathing","Promise that a single drainage always cures the disorder","Stop further assessment because cytology showed lymphocytes"],"answer":0,"why":"Long-term outcome depends on cause and recurrence. Owners need clear respiratory distress warnings and an individualized reassessment plan.","tag":"Discharge and follow-up","findings":"Nimbus leaves with a written respiratory monitoring and specialty follow-up plan."}]},{"id":"hospital-horse-colic-26","name":"Atlas · horse with acute colic","emoji":"🐎","species":"Horse","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"A 12-year-old gelding is pawing, looking at his flank and repeatedly attempting to lie down. This simulated large-animal journey follows urgent history, perfusion, diagnostics, referral decisions and postoperative or medical monitoring.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"A caller reports a horse rolling repeatedly with severe pain. What is the safest triage advice?","options":["Arrange immediate veterinary assessment and advise safe handling without putting people at risk","Recommend waiting until morning regardless of severity","Ask the owner to exercise the horse vigorously to exhaustion"],"answer":0,"why":"Severe or persistent colic can reflect strangulating or obstructive disease. Owner and handler safety is essential; urgent veterinary evaluation and preparation for referral may be needed.","tag":"Emergency intake","findings":"The owner reports reduced manure output and sudden severe pain."},{"room":"reception","q":"Which history most helps evaluate an equine colic case?","options":["Onset and duration, manure and water intake, feeding changes, previous colic and administered medications","Whether the horse won a ribbon last month","Favorite pasture companion only"],"answer":0,"why":"Colic differentials are shaped by timing, fecal production, diet, previous episodes and any analgesics that might mask severity.","tag":"History","findings":"Atlas is tachycardic and has tacky mucous membranes on examination."},{"room":"exam","q":"Heart rate is 72 bpm. Example adult horse resting interval is approximately 28–44 bpm. What does this imply in a painful horse?","options":["Marked tachycardia raises concern about pain, hypovolemia or cardiovascular compromise","Normal resting physiology, so no further assessment is needed","A specific diagnosis of gastric ulceration is confirmed"],"answer":0,"why":"Heart rate must be interpreted alongside pain, perfusion, temperature and gastrointestinal findings. Persistent tachycardia increases concern for severe disease but does not localize the lesion.","tag":"Physical exam","findings":"Nasogastric intubation produces significant reflux, and abdominal ultrasound raises concern for small-intestinal distension."},{"room":"exam","q":"What is the most appropriate next step given severe pain, reflux and suspected distended small intestine?","options":["Urgent referral/surgical consultation while continuing stabilization and decompression as indicated","Feed a large grain meal to stimulate motility","Assume simple gas colic because pain medication helped briefly"],"answer":0,"why":"Reflux with distended small intestine can indicate obstruction. Prompt surgical assessment may be critical. Interventions depend on examination findings and safety; avoid indiscriminate feeding.","tag":"Diagnostic reasoning","findings":"A referral clinician identifies a small-intestinal lesion requiring surgery."},{"room":"treatment","q":"Following surgery, what inpatient trends are particularly important?","options":["Perfusion, pain, nasogastric reflux, gastrointestinal function, hydration and electrolyte/acid–base status","Only coat condition","One initial heart rate with no subsequent reassessment"],"answer":0,"why":"Reflux, ileus, endotoxemia, electrolyte shifts and incisional complications can occur after abdominal surgery. Trends guide fluids, analgesia, nutrition and reassessment.","tag":"Hospital monitoring","findings":"Atlas gradually regains gastrointestinal motility and manure output."},{"room":"treatment","q":"Which discharge counseling is most appropriate?","options":["Gradual veterinarian-directed feeding and activity plan, incision checks, manure/appetite monitoring and urgent return signs","Immediate unrestricted work and grain feeding regardless of surgical instructions","No follow-up after hospital discharge"],"answer":0,"why":"Recovery after abdominal surgery requires structured refeeding, wound surveillance and progressive activity, with prompt reassessment for recurrent colic, reduced manure or fever.","tag":"Recovery and prevention","findings":"Atlas is discharged under a written recovery protocol."}]},{"id":"hospital-goat-obstructive-urolithiasis-26","name":"Biscuit · wether with urinary obstruction","emoji":"🐐","species":"Goat","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"A young pet wether presents with repeated straining, vocalization and reduced urine production. This large-animal case links nutrition history, emergency bladder assessment, renal pathology and treatment choices.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"Biscuit repeatedly strains but passes no visible urine. What is the immediate concern?","options":["Potential urethral obstruction and bladder rupture risk requiring urgent veterinary assessment","Routine behavioral marking that never needs examination","A normal response to weather change"],"answer":0,"why":"Male small ruminants, especially wethers, are predisposed to obstructive urolithiasis. Untreated obstruction can cause metabolic derangements, rupture and uroabdomen.","tag":"Triage","findings":"The owner has not seen a normal urine stream for many hours."},{"room":"reception","q":"Which additional history is most useful?","options":["Diet including concentrate and mineral balance, water intake, castration age and time since last urination","Color of halter only","Whether Biscuit prefers certain toys"],"answer":0,"why":"Urinary stone risk is influenced by diet, mineral intake, urine concentration and anatomy. History aids prevention planning but cannot replace prompt evaluation.","tag":"History","findings":"Biscuit appears painful, has a distended abdomen and no visible urinary output."},{"room":"exam","q":"Ultrasound identifies free abdominal fluid and a poorly distended urinary bladder. What complication must be investigated?","options":["Uroabdomen from urinary tract rupture","Normal urinary flow","Confirmed intestinal torsion without other findings"],"answer":0,"why":"Urethral obstruction can cause bladder or urethral rupture. Abdominal fluid sampling and comparison of peritoneal versus blood creatinine can aid confirmation.","tag":"Imaging and localization","findings":"Abdominal fluid creatinine is greater than serum creatinine, supporting urine leakage; the lab's sampling and comparison methods are reviewed."},{"room":"exam","q":"Which metabolic abnormalities are particularly concerning with uroabdomen?","options":["Hyperkalemia, hyponatremia and acid–base disturbances","Isolated high cholesterol as the sole emergency risk","Guaranteed normal electrolytes if the bladder has ruptured"],"answer":0,"why":"Sequestration and exchange of electrolytes across the peritoneum, impaired urine excretion and dehydration can produce serious metabolic changes. Obtain ECG and serial electrolytes as indicated.","tag":"Clinical pathology","findings":"The surgical team plans stabilization and urinary diversion or repair based on the rupture site and patient's condition."},{"room":"treatment","q":"What treatment principle best fits an obstructed wether with suspected rupture?","options":["Stabilize metabolic and cardiovascular abnormalities and obtain urgent surgical management appropriate to location and severity","Give a diuretic as definitive relief of all obstructions","Wait for spontaneous rupture to decompress the urinary tract"],"answer":0,"why":"Relieving obstruction and repairing or bypassing damaged urinary structures may be essential; intervention varies by lesion and availability of surgical options.","tag":"Treatment","findings":"Urinary drainage is established and Biscuit's electrolyte abnormalities begin to resolve."},{"room":"treatment","q":"Which owner plan helps reduce recurrence?","options":["Individualized forage-based diet/mineral review, adequate water, monitoring of urination and veterinary follow-up","Unlimited grain concentrate without nutritional evaluation","Assume prior obstruction cannot recur"],"answer":0,"why":"Stone prevention is driven by suspected composition, dietary calcium:phosphorus balance, water access and husbandry. No single strategy prevents every calculus type.","tag":"Monitoring and prevention","findings":"Biscuit is discharged with a diet, hydration and urinary-output monitoring plan."}]}]});
